    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_box_autoadd_http_mode(self.httpMode, serializer);
    sse_encode_bool(self.verifySsl, serializer);
    sse_encode_bool(self.followRedirects, serializer);
    sse_encode_bool(self.followOriginalMethod, serializer);
    sse_encode_bool(self.followAuthHeader, serializer);
    sse_encode_bool(self.removeReferer, serializer);
    sse_encode_bool(self.strictHttpParser, serializer);
    sse_encode_bool(self.disableCookieJar, serializer);
    sse_encode_u_32(self.maxRedirects, serializer);
    sse_encode_disabled_tls(self.disabledTls, serializer);
  }

  @protected
  void sse_encode_response(Response self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_16(self.status, serializer);
    sse_encode_String(self.statusText, serializer);
    sse_encode_String(self.httpVersion, serializer);
    sse_encode_list_header(self.headers, serializer);
    sse_encode_String(self.body, serializer);
    sse_encode_CastedPrimitive_u_64(self.sizeBytes, serializer);
    sse_encode_CastedPrimitive_u_64(self.elapsedMs, serializer);
  }

  @protected
  void sse_encode_sent(Sent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_response(self.response, serializer);
    sse_encode_list_String(self.unresolved, serializer);
    sse_encode_list_cookie(self.cookies, serializer);
  }

  @protected
  void sse_encode_settings(Settings self, SseSerializer serializer) {
